class DeviceGatewayMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next):
        client_id = request.headers.get("X-Device-Client-ID")
        request.state.client_id = client_id
        return await call_next(request)

app.add_middleware(DeviceGatewayMiddleware)

@app.get("/api/v1/devices/{device_uuid}/sampling-rates")
async def get_sampling_config(
    device_uuid: str,
    request: Request,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    device = db.query(IoTDevice).filter(
        IoTDevice.uuid == device_uuid,
        IoTDevice.owner_id == current_user.id
    ).first()
    if not device:
        raise HTTPException(status_code=404, detail="Device not found")
    return {"device_uuid": device.uuid, "sample_rate_hz": device.sample_rate_hz, "sensors": device.active_sensors}
